
/* =====================================================================
   UI — štampa izvještaja na IDSS memorandumu (A4). Dokument se gradi samo
   pomoću h()/textContent; zaglavlje i podnožje su slike memoranduma.
   ===================================================================== */
(function (U) {
  'use strict';
  const L = Logika, h = U.h;
  const MEMO = {"glava": "data:image/png;base64,", "podnozje": "data:image/png;base64,"};
  const C = () => U.citanje;
  const danas = () => { const p = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Sarajevo', day: '2-digit', month: '2-digit', year: 'numeric' }).formatToParts(new Date()); const g = t => p.find(x => x.type === t).value; return `${g('day')}.${g('month')}.${g('year')}.`; };
  function vr(o, sp) {
    const v = o ? o[sp.k] : undefined;
    if (v === undefined || v === null || v === '' || (Array.isArray(v) && !v.length)) return '—';
    if (Array.isArray(v)) return v.join(', ');
    return sp.t === 'd' ? L.fmtDatum(v) : String(v);
  }
  const redovi = (o, spec) => spec.filter(sp => !sp.uslov || sp.uslov(o || {})).map(sp => h('tr', {}, h('th', {}, sp.l), h('td', {}, vr(o, sp))));
  const tab = (rows, klasa) => h('table', { class: 'st-tab ' + (klasa || '') }, h('tbody', {}, rows));
  const naslov = (br, t) => h('h2', { class: 'st-h2' }, `${br}. ${t}`);
  const stavke = (lista, spec, ime, prazno) => (!lista || !lista.length) ? [h('p', { class: 'st-prazno' }, prazno)]
    : lista.map((x, i) => h('div', { class: 'st-stavka' }, h('div', { class: 'st-st-naslov' }, ime(x, i)), tab(redovi(x, spec))));

  function dokument(izv) {
    const c = C(), s = izv.sadrzaj || {}, ped = izv.psiholog || U.A.profil || {}, nacrt = !!izv.nacrt || izv.status === 'nacrt' || izv.status === 'vracen';
    const odobren = izv.status === 'odobren';
    const stanje = U.STATUS[izv.status] || izv.status;
    const d = [];
    // zaglavlje memoranduma (prva stranica)
    d.push(h('div', { class: 'st-memo' }, h('img', { class: 'st-logo', src: MEMO.glava, alt: 'Internationale Deutsche Schule Sarajevo' }),
      h('div', { class: 'st-broj' }, h('div', {}, 'Broj: ______________'), h('div', {}, 'Sarajevo, ' + danas()))));
    d.push(h('h1', { class: 'st-h1' }, 'Mjesečni izvještaj psihologa'), h('p', { class: 'st-pod' }, `za period: ${U.naslovPerioda(izv.godina, izv.mjesec)}`));
    d.push(tab([
      h('tr', {}, h('th', {}, 'Primalac'), h('td', {}, 'Direktor škole')),
      h('tr', {}, h('th', {}, 'Psiholog'), h('td', {}, ped.ime || '—')),
      ped.email || ped.telefon ? h('tr', {}, h('th', {}, 'Kontakt'), h('td', {}, [ped.email, ped.telefon].filter(Boolean).join(' · '))) : null,
      h('tr', {}, h('th', {}, 'Stanje izvještaja'), h('td', {}, stanje + (nacrt && izv.status === 'nacrt' ? ' (nije podnesen)' : ''))),
      izv.podnesen_u ? h('tr', {}, h('th', {}, 'Podneseno'), h('td', {}, `${U.fmtVrijeme(izv.podnesen_u)} · podnošenje br. ${izv.ciklus}${izv.na_vrijeme === null || izv.na_vrijeme === undefined ? '' : izv.na_vrijeme ? ' · u roku' : ' · nakon roka'}`)) : null,
    ].filter(Boolean), 'st-meta'));
    let br = 1;
    // pokazatelji
    if (izv.kpi) {
      const k = izv.kpi, a = k.kpi01, k3 = k.kpi03, adm = s.administracija || {}, rs = ((s.radionice || {}).stavke || []).filter(x => x.status === 'održano');
      const nz = x => (x === undefined || x === null ? '—' : x);
      d.push(h('h3', { class: 'st-h3' }, 'Pokazatelji'), tab([
        h('tr', {}, h('th', {}, 'Radionice i obuke zavedene u zapis QP 05'), h('td', {}, `${rs.filter(x => x.qp05_zapis === 'Da').length} od ${rs.length} održanih`)),
        h('tr', {}, h('th', {}, 'Povjerljivost i saglasnosti'), h('td', {}, `povjerljivost: ${nz(adm.povjerljivost)}; saglasnosti roditelja: ${nz(adm.saglasnosti)}`)),
        h('tr', {}, h('th', {}, 'Opservacije u razredu'), h('td', {}, a.nije_planirano ? 'nisu planirane' : `realizirano ${a.realizirano} od ${a.planirano}${a.stopa === null ? '' : ' (' + a.stopa + '%)'}`)),
        h('tr', {}, h('th', {}, 'Individualna savjetovanja sa učenicima'), h('td', {}, String(nz(k.kpi02.sesije)))),
        h('tr', {}, h('th', {}, 'Rizici'), h('td', {}, `aktivnih ${k3.aktivno_3c}, riješeno ${k3.rijeseno_3a}, prenesenih ${k3.preneseno_3b}, rok mjere probijen ${k3.kasne_mjere}`)),
      ]));
    }
    // sadržaj
    ['ucenici', 'nastavnici', 'roditelji'].forEach(k => { d.push(naslov(br++, c.NASLOV_SEK[k]), tab(redovi(s[k], c.SPEC[k]))); });
    const rad = s.radionice || {};
    d.push(naslov(br++, 'Radionice i obuke'), ...stavke(rad.stavke, c.SPEC_RAD, (x, i) => `${i + 1}. ${x.naslov || 'Radionica'}`, 'Nema evidentiranih radionica.'));
    if (rad.nema_obrazlozenje) d.push(tab([h('tr', {}, h('th', {}, 'Obrazloženje izostanka'), h('td', {}, rad.nema_obrazlozenje))]));
    d.push(naslov(br++, 'Usavršavanje i supervizija'), ...stavke((s.usavrsavanje || {}).stavke, c.SPEC_USV, (x, i) => `${i + 1}. ${x.naslov || 'Usavršavanje'}`, 'Nema unesenog usavršavanja.'));
    d.push(naslov(br++, 'Rizici'), ...stavke(izv.rizici, c.SPEC_RIZ, x => `${x.kod || 'Rizik'}${x.prenesen ? ' (prenesen iz ranijeg mjeseca)' : ''}`, 'Nema evidentiranih rizika.'));
    d.push(naslov(br++, 'QMS (QP 05), povjerljivost i administracija'), tab(redovi(s.administracija, c.SPEC.administracija)));
    d.push(naslov(br++, 'Zaključak i plan'), tab(redovi(s.zakljucak, c.SPEC.zakljucak)));
    d.push(naslov(br++, 'Preporuke direktoru'));
    const pr = izv.preporuke || [];
    if (!pr.length) d.push(h('p', { class: 'st-prazno' }, 'Nema preporuka u ovom izvještaju.'));
    pr.forEach((p, i) => d.push(h('div', { class: 'st-stavka' }, h('div', { class: 'st-st-naslov' }, `${i + 1}. ${p.naslov}`),
      tab([h('tr', {}, h('th', {}, 'Obrazloženje'), h('td', {}, p.obrazlozenje || '—')), h('tr', {}, h('th', {}, 'Utjecaj na resurse'), h('td', {}, p.utjecaj || '—')),
        p.odluka ? h('tr', {}, h('th', {}, 'Odluka direktora'), h('td', {}, p.odluka + (p.komentar_direktora ? ' — ' + p.komentar_direktora : ''))) : null].filter(Boolean)))));
    if (odobren) d.push(naslov(br++, 'Odluka direktora'), tab([h('tr', {}, h('th', {}, 'Stanje'), h('td', {}, 'Izvještaj je odobren')),
      izv.direktor_ocjena !== null && izv.direktor_ocjena !== undefined ? h('tr', {}, h('th', {}, 'Ocjena kvaliteta'), h('td', {}, `${izv.direktor_ocjena} od 5`)) : null,
      izv.direktor_napomena ? h('tr', {}, h('th', {}, 'Napomena'), h('td', {}, izv.direktor_napomena)) : null].filter(Boolean)));
    d.push(h('div', { class: 'st-potpisi' }, h('div', {}, h('div', { class: 'linija' }), 'Psiholog', h('br'), ped.ime || ''), h('div', {}, h('div', { class: 'linija' }), 'Direktor škole')));
    if (!odobren) d.push(h('p', { class: 'st-napomena' }, 'Izvještaj još nije odobren.'));
    return d;
  }

  U.stampaj = function (izv) {
    let ko = document.getElementById('stampa'); if (ko) ko.remove();
    ko = h('div', { id: 'stampa', 'aria-hidden': 'true' },
      h('img', { class: 'st-podnozje', src: MEMO.podnozje, alt: '' }),
      h('table', { class: 'st-okvir' }, h('thead', {}, h('tr', {}, h('td', {}, h('div', { class: 'st-r-gore' })))),
        h('tbody', {}, h('tr', {}, h('td', { class: 'st-sadrzaj' }, dokument(izv)))),
        h('tfoot', {}, h('tr', {}, h('td', {}, h('div', { class: 'st-r-dolje' }))))));
    document.body.appendChild(ko);
    const naslovStari = document.title;
    document.title = `IDSS izvještaj psihologa ${U.naslovPerioda(izv.godina, izv.mjesec)}`;
    const kraj = () => { document.title = naslovStari; const e = document.getElementById('stampa'); if (e) e.remove(); window.removeEventListener('afterprint', kraj); };
    window.addEventListener('afterprint', kraj);
    const slike = [...ko.querySelectorAll('img')]; Promise.all(slike.map(i => (i.decode ? i.decode().catch(() => {}) : Promise.resolve()))).then(() => setTimeout(() => window.print(), 50));
  };
})(UI);
